def test_plot_main(temp_dir, resource_paths, data, data_atomics):

    # main_image
    plotter = GraphPlotter()
    plotter.plot_main(resource_paths, None, data, None, data_atomics, RDE_CONFIG_YAML)
    main_image = temp_dir / "XPS.png"
    assert main_image.exists(), "The plot was not saved correctly."
    if os.path.exists(main_image):
        os.remove(main_image)

    # other_image
    # MEMO: The data in the .spe file is one block, so it cannot be checked here;
    #       it will be checked by testing the .pro file.
